contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address adr, uint amount) public payable {
        require(address(this).balance >= amount);
        // fund c so its balance is nonzero and controllable
        c.multiplicate(address(this));
        uint pre = address(c).balance;
        if (pre > 0) {
            uint amount2 = amount % pre; // ensure amount2 < pre
            bool reverted;
            c.multiplicate{value: amount2}(adr);
            reverted = false;
            assert(!reverted && address(c).balance == pre);
        } else {
            // balance is zero: any send value is >= balance, so multiplicate transfers everything out
            c.multiplicate{value: amount}(adr);
            assert(address(c).balance == 0);
        }
    }
    receive() external payable {}
}

